<?php
declare(strict_types=1);
require __DIR__.'/mailbox-recovery-support.php';
$config=json_decode(file_get_contents($argv[1]),true);mailboxCase(static function(MailboxEnvironment $m)use($config):void{
    $d=$m->begin();file_put_contents($config['coordination'],json_encode(['database'=>$m->e->directory.'/registration.sqlite']));chmod($config['coordination'],0600);
    $urls=[];foreach(['verify_registration','verify_address_old','verify_address_new','cancel_change','recover_account','recover_address'] as $type){$urls[$type]='https://account.example.test/'.$type;}$templates=new SoSecurity\Account\MailTemplates('account-test',new SoSecurity\Account\Address('security@example.test'),$urls);$policies=[];foreach(['site','transport','target','subject'] as $name){$policies[$name]=new SoSecurity\RateLimit\BudgetPolicy('fixed_window',1000,60);}$budgets=new SoSecurity\Account\SendBudgets(new SoSecurity\Storage\FileStore($m->e->directory.'/budgets','mailbox-smtp',$m->e->clock,5000),'account-test',str_repeat('s',32),$policies,$m->e->clock);
    $transport=new SoSecurity\Account\SmtpTransport('owned-mailbox','smtp.example.test',$config['port'],'127.0.0.1','tls',null,$config['ca']);$sender=$m->service->dispatcher('worker',$budgets,$templates,$transport,static function():bool{return true;});$result=null;$error=null;try{$result=$sender->sendNext(1);}catch(SoSecurity\Exception\SecurityException $failure){$error=$failure->reason();}
    $confirmed=$result!==null&&$result['state']==='submitted'?$m->confirm($d):false;$q=$m->e->pdo->prepare('SELECT status FROM sosecurity_outbox_records WHERE namespace=:namespace AND order_no=2');$q->execute(['namespace'=>SoSecurity\Outbox\State::namespace('account-test','tenant','account-mailbox-recovery')]);echo json_encode(['result'=>$result,'error'=>$error,'confirmed'=>$confirmed,'address'=>$m->e->account()['address'],'status'=>$m->e->account()['status'],'queue'=>$q->fetchColumn(),'token_hash'=>hash('sha256',$d->notice()->token())])."\n";
});
